        }
    }

    public void forceSaveState() {
        addJsToWebView("window.callUICallback(forceSaveState,'failure');");
    }

    public void onActivityLifeCycleEvent(String event) {
        this.addJsToWebView("window.onActivityLifeCycleEvent('"+event+"')");
    }

